262	    #[test]
263	    fn from_env_seeds_from_remote_vars() {
264	        let _lock = ENV_LOCK.lock().unwrap();
265	        std::env::set_var("REMOTE_HOST", "fpga-ci.example.com");
266	        std::env::set_var("REMOTE_USER", "ci");
