271	        let cfg = RemoteConfig::from_env().expect("from_env with REMOTE_HOST set");
272	        assert_eq!(cfg.host, "fpga-ci.example.com");
273	        assert_eq!(cfg.user, "ci");
274	        assert_eq!(cfg.port, 2323);
275	        assert_eq!(
276	            cfg.key_file.as_deref(),
277	            Some(Utf8PathBuf::from("/tmp/ci_key").as_path())
278	        );
279	        // from_env normalizes a tool-root to `<root>/settings64.sh` so
280	        // the remote runner's `source <path>` actually works.
281	        assert_eq!(
282	            cfg.xilinx_settings.as_deref(),
283	            Some("/opt/xilinx/settings64.sh")
284	        );
285	        assert!(!cfg.ssh_multiplex);
286	
287	        for k in [
288	            "REMOTE_HOST",
289	            "REMOTE_USER",
290	            "REMOTE_PORT",
291	            "REMOTE_KEY_FILE",
292	            "REMOTE_XILINX_TOOL_PATH",
293	            "REMOTE_SSH_MULTIPLEX",
294	        ] {
295	            std::env::remove_var(k);
296	        }
297	    }
